import yaml, re
d=yaml.safe_load(open('.coordination/mining/v2/day-008.yaml'))
src=open('claude-dev-log-diary/day-008.md').read()
def norm(s): return re.sub(r'\s+',' ',s).strip()
nsrc=norm(src)
bad=[]
def check(q, loc, where):
    if not q: return
    q=q.strip()
    for prefix in ('> ',):
        if q.startswith(prefix): q=q[len(prefix):]
    if norm(q) not in nsrc: bad.append((where, loc, q[:90]))
for p in d['philosophy']: check(p.get('quote'), p['loc'], 'phil')
for r in d['skill_rules']: check(r.get('quote'), r['evidence'], 'rule')
for f in d['failure_modes']: check(f.get('quote'), f['loc'], 'fail')
for p in d['pairing_rules']: check(p.get('quote'), p['evidence'], 'pair')
print('MISMATCHES:', len(bad))
for b in bad: print(b)
EOF
